/// <summary>
///     The <c>AVAInventTransferOrdersFrm_InventTransferLineDS_Extension</c> class is the extension for <c>InventTransferOrders</c>
/// </summary>
[ExtensionOf(formDataSourceStr(InventTransferOrders, InventTransferLine))]
final class AVAInventTransferOrdersFrm_InventTransferLineDS_Extension
{
    public InventTransferLine   frmInventTransferLineDelete;

}

Method.Source:
/// <summary>
///    AVA <c>displayOption</c> method.
/// </summary>
/// <param name="_record">
///    <c>Common</c> as type
/// </param>
/// <param name="_options">
///    <c>FormRowDisplayOption</c> as type
/// </param>
public void displayOption(Common _record, FormRowDisplayOption _options)
{
    InventTransferLine  locInventTransferLine;

    int                 locItemSetColor;
    int                 locItemSetColorExpanded;
    int                 locItemSetColorComponent;

    next displayOption(_record, _options);

    locInventTransferLine           = _record;

    if(element.frmAVAItemSetParameters.RecId)
    {
        locItemSetColor             = element.frmAVAItemSetParameters.ItemSetBGColor;
        locItemSetColorExpanded     = element.frmAVAItemSetParameters.ItemSetBGColorExpanded;
        locItemSetColorComponent    = element.frmAVAItemSetParameters.ItemSetBGColorComponent;
    }
    else
    {
        locItemSetColor             = 16744576; // FF8080 or 255,128,128 or WinAPI::RGB2int(255, 128, 128)    // light red
        locItemSetColorExpanded     = 65505;    // 00FFE1 or 0,255,255  or WinAPI::RGB2int(0, 255, 255)       // turquoise
        locItemSetColorComponent    = 8454118;  // 80FFE6 or 128,255,255  or WinAPI::RGB2int(128, 255, 255)   // light turquoise
    }

    if(     locInventTransferLine.AVAItemSetExpanded
        &&  locItemSetColorExpanded                 )
    {
        _options.backColor(locItemSetColorExpanded);
    }
    else if(    locInventTransferLine.AVAItemSet
            &&  locItemSetColor                 )
    {
        _options.backColor(locItemSetColor);
    }
    else if(    locInventTransferLine.AVAItemSetParent
            &&  locItemSetColorComponent            )
    {
        _options.backColor(locItemSetColorComponent);
    }
    /*
    else
    {
    _options.clearBackColor();
    }
    */
}

/// <summary>
///    AVA <c>active</c> method.
/// </summary>
/// <returns>
///    <c>int</c> as return value
/// </returns>
public int active()
{
    int     retVal;
    boolean locboolean;

    element.frmFDSInventTransferLine            = element.InventTransferLine_DS;

    locboolean                                  = element.frmFDSInventTransferLine.allowDelete(true);
    locboolean                                  = element.frmFDSInventTransferLine.allowEdit(true);

    locboolean                                  = element.frmFDSInventTransferLine.object(fieldNum(InventTransferLine, QtyTransfer)).allowEdit(true);
    locboolean                                  = element.frmFDSInventTransferLine.object(fieldNum(InventTransferLine, OverDeliveryPct)).allowEdit(true);
    locboolean                                  = element.frmFDSInventTransferLine.object(fieldNum(InventTransferLine, UnderDeliveryPct)).allowEdit(true);

    retVal = next active();

    element.frmFDSInventTransferLineAllowDelete = element.frmFDSInventTransferLine.allowDelete();
    element.frmFDSInventTransferLineAllowEdit   = element.frmFDSInventTransferLine.allowEdit();

    element.frmInventTransferLineQtyTransferAllowEdit       = element.frmFDSInventTransferLine.object(fieldNum(InventTransferLine, QtyTransfer)).allowEdit();
    element.frmInventTransferLineOverDeliveryPctAllowEdit   = element.frmFDSInventTransferLine.object(fieldNum(InventTransferLine, OverDeliveryPct)).allowEdit();
    element.frmInventTransferLineUnderDeliveryPctAllowEdit  = element.frmFDSInventTransferLine.object(fieldNum(InventTransferLine, UnderDeliveryPct)).allowEdit();

    element.avaCheckInventTransferTableControls();
    element.avaCheckInventTransferLineControls();

    return retVal;
}

/// <summary>
///    AVA <c>write</c> method.
/// </summary>
public void write()
{
    FormDataSource      locInventTransferLineDS;
    InventTransferLine  locInventTransferLine;

    next write();

    locInventTransferLineDS = element.InventTransferLine_DS;
    locInventTransferLine = locInventTransferLineDS.cursor();

    if (locInventTransferLine.AVAItemSet)
    {
        element.avaRefreshInventTransferLineDS();
    }
}

/// <summary>
///    AVA <c>delete</c> method.
/// </summary>
public void delete()
{
    FormDataSource      locInventTransferLineDS;
    InventTransferLine  locInventTransferLine;

    locInventTransferLineDS             = element.InventTransferLine_DS;
    locInventTransferLine               = locInventTransferLineDS.cursor();
    element.frmInventTransferLineDelete = locInventTransferLine;

    next delete();

    if (    element.frmInventTransferLineDelete.AVAItemSet 
        ||  element.frmInventTransferLineDelete.AVAItemSetComponent)
    {
        element.avaRefreshInventTransferLineDS();
    }
}

/// <summary>
///    AVA <c>deleted</c> method.
/// </summary>
public void deleted()
{
    FormDataSource      locInventTransferLineDS;
    InventTransferLine  locInventTransferLine;

    locInventTransferLineDS = element.InventTransferLine_DS;
    locInventTransferLine = locInventTransferLineDS.cursor();

    next deleted();

    if (element.frmInventTransferLineDelete.AVAItemSet)
    {
        locInventTransferLineDS.research(true);
    }
}
